style.css:
@-moz-document domain("eracast.cc") {
/* 1. Hide the "under development" modal overlay and backdrop */
  .modal-backdrop,
  .modal-dialog,
  div[class*="under-development"],
  div[class*="disabled-overlay"],
  div[id*="development"],
  .disabled-feature-overlay,
  .under-construction-banner {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
  }

  /* 2. Re-enable pointer events and scrolling on body/editor wrapper if locked */
  body, 
  body.modal-open, 
  #creator-editor-container, 
  .editor-wrapper,
  .ytve-container {
    overflow: auto !important;
    pointer-events: auto !important;
    filter: none !important;
    opacity: 1 !important;
  }
}
